parameters.jsCode:
// Производные значения. Заголовок задачи собирается здесь по жёсткому
// формату: по нему же ниже ищется дубликат, и формат должен совпадать.
const p = $input.first().json;
return [{ json: { ...p,
  issueTitle: `Релиз ${p.tagTo}: чек-лист выкатки`,
  reportPath: `/workspace/reports/release-${p.tagTo}.md`,
  templatePath: '/workspace/release/notes-template.md'
}}];

// Один запрос compare отдаёт все коммиты диапазона. Разворачиваем по
// одному: следующий узел сходит за файлами каждого, а пути к файлам
// нужны, чтобы определять признаки риска.
const cmp = $input.first().json;
const ctx = $('Производные значения').first().json;
const commits = cmp.commits || [];
if (!commits.length) throw new Error('между тегами нет коммитов');
return commits.map(c => ({ json: { sha: c.sha, owner: ctx.owner, repo: ctx.repo } }));

// Сжимаем коммит до минимума и СРАЗУ размечаем признаки риска по путям.
// Проверка «лежит ли файл в db/migrations» детерминирована, и отдавать её
// модели незачем: это стоило бы токенов и давало бы разброс. Модели
// остаётся суждение: что из размеченного важно дежурному, как это
// сформулировать и какие пять пунктов оставить.
//
// Пути файлов в payload НЕ попадают: после разметки они не нужны, а весят
// примерно половину всего списка коммитов.
const ctx = $('Производные значения').first().json;

function riskOf(message, files) {
  const r = [];
  const has = (frag) => files.some(f => f.indexOf(frag) === 0 || f.indexOf('/' + frag) >= 0);
  if (has('db/migrations')) r.push('миграция');
  if (has('services/payments') || has('services/orders')) r.push('оплата-заказы');
  if (/откат|хотфикс/i.test(message)) r.push('откат-хотфикс');
  if (has('.github/workflows') || has('deploy/')) r.push('конфигурация-выкатки');
  return r;
}

const commits = $input.all().map(i => {
  const c = i.json;
  const msg = ((c.commit && c.commit.message) || '').split(String.fromCharCode(10))[0];
  const files = (c.files || []).map(f => f.filename);
  const risk = riskOf(msg, files);
  const out = { sha: (c.sha || '').slice(0, 7), msg };
  if (risk.length) out.risk = risk;
  return out;
});

const risky = commits.filter(c => c.risk).length;
return [{ json: { ...ctx, commitCount: commits.length, riskyCount: risky, commits } }];

// Проверка дубликата кодом, а не моделью. Ищем точное совпадение
// заголовка среди задач в ЛЮБОМ состоянии: тег не переиспользуется,
// поэтому закрытая задача на тот же тег тоже значит «уже обработано».
// Раньше это правило держалось на том, что модель не забудет вызвать
// list_issues. Теперь обойти его она не может.
//
// Здесь же читаем чек-лист с диска: каталог /workspace примонтирован
// и в n8n, и в MCP-сервер файлов. Так агент Б не тратит свою минуту
// бюджета на чтение файла.
const fs = require('fs');
const ctx = $('Сжать коммиты').first().json;
const issues = $input.all().map(i => i.json).filter(x => x && x.title);
const matches = issues.filter(i => i.title === ctx.issueTitle)
                      .sort((a, b) => a.number - b.number);
const found = matches[0];
let checklist = '';
try { checklist = fs.readFileSync('/workspace/release/checklist.md', 'utf8'); }
catch (e) { checklist = 'ЧЕК-ЛИСТ НЕДОСТУПЕН: ' + e.message; }
return [{ json: { ...ctx,
  duplicate: Boolean(found),
  duplicateUrl: found ? found.html_url : null,
  duplicateNumber: found ? found.number : null,
  checklistRepoPath: 'lab8-morning-digest/stand/workspace/release/checklist.md',
  checklist
}}];

