parameters.jsCode:
// Документ больше не едет внутри JSON-аргумента вызова инструмента.
// Причина измерена: qwen обрывал длинную строку в аргументах write_file
// на 224 токенах вывода и обрыва не замечал, а gpt-oss писал целиком,
// но тратил на размышление столько, что не влезал в лимит Groq
// OTPM 1000 токенов вывода в минуту. Модель отдаёт текст, файл кладёт
// этот узел, и запись перестаёт зависеть от умения модели собирать JSON.
const fs = require('fs');
const ctx = $('Проверить дубль и прочитать чек-лист').first().json;
const text = ($('Агент А: release notes').first().json.output || '').trim();
const NL = String.fromCharCode(10);

const required = ['## Требует внимания', '## Что увидят',
                  '## Внутренние изменения', '## Миграции'];
const missing = required.filter(h => text.indexOf(h) < 0);
if (text.length < 400) {
  throw new Error('сводка слишком короткая: ' + text.length + ' символов');
}
if (missing.length) {
  throw new Error('в сводке нет разделов: ' + missing.join('; '));
}

fs.writeFileSync(ctx.reportPath, text + NL, 'utf8');

// Проверяем не свою же переменную, а файл на диске: каталог смонтирован
// и в n8n, и в MCP-сервер файлов, и ошибка монтирования видна только так.
const st = fs.statSync(ctx.reportPath);
const age = (Date.now() - st.mtimeMs) / 1000;
if (st.size < 400 || age > 60) {
  throw new Error('файл записан неверно: ' + st.size + ' байт, возраст ' + age + ' с');
}

return [{ json: Object.assign({}, ctx, { reportBytes: st.size, reportChars: text.length }) }];

