// Тело задачи приходит текстом от агента, а не аргументом вызова
// инструмента: длинную строку в аргументе модель не дотягивает.
// Проверяем здесь, до записи, потому что созданную задачу уже не отозвать.
const ctx = $('Проверить дубль и прочитать чек-лист').first().json;
const body = ($('Агент Б: тело задачи').first().json.output || '').trim();

if (body.length < 800) {
  throw new Error('тело задачи слишком короткое: ' + body.length +
                  ' символов, ожидался чек-лист целиком');
}
const tail = body.slice(-1);
if (tail !== '.' && tail !== ')' && tail !== '!' && tail !== ':') {
  throw new Error('тело задачи оборвано на полуслове, последние символы: ' +
                  JSON.stringify(body.slice(-40)));
}

// Эталон: тот же чек-лист, прочитанный с диска узлом дедупликации.
// Агент читает его из репозитория через get_file_contents, и сверка
// с эталоном ловит случай, когда он потерял или выдумал пункты.
const expected = (ctx.checklist.match(/^\s*\d+\./gm) || []).length;
const got = (body.match(/^\s*\d+\./gm) || []).length;
if (got < expected) {
  throw new Error('в теле задачи ' + got + ' пунктов чек-листа из ' + expected);
}

return [{ json: { title: ctx.issueTitle, body, bodyChars: body.length,
                  checklistPoints: got, expectedPoints: expected } }];

// Ответ GitHub на создание это и есть сохранённое состояние задачи.
// Сверяем с тем, что отправляли: так видно и усечение на стороне API,
// и случай, когда запись не дошла вовсе.
const sent = $('Собрать тело задачи').first().json;
const issue = $input.first().json;

if (!issue || !issue.number) {
  throw new Error('GitHub не вернул номер созданной задачи');
}
const stored = (issue.body || '').trim();
if (stored.length < sent.bodyChars) {
  throw new Error('тело задачи #' + issue.number + ' сохранено не полностью: ' +
                  'отправляли ' + sent.bodyChars + ', записано ' + stored.length);
}
return [{ json: { action: 'создана задача', issueNumber: issue.number,
                  issueUrl: issue.html_url, bodyChars: stored.length,
                  checklistPoints: sent.checklistPoints } }];

// Узел выше отдаёт полный ответ, поэтому элемент здесь есть всегда,
// даже когда комментариев ноль. Это и есть страховка: без неё n8n
// обрывал ветку молча и прогон отчитывался успехом без комментария.
const ctx = $('Проверить дубль и прочитать чек-лист').first().json;
const resp = $input.first().json;
const list = Array.isArray(resp.body) ? resp.body : [];

if (!list.length) {
  throw new Error('агент не оставил комментарий в задаче #' + ctx.duplicateNumber);
}
const last = list[list.length - 1];
const body = (last.body || '').trim();
if (body.length < 100) {
  throw new Error('комментарий слишком короткий: ' + body.length + ' символов');
}
// Обрыв аргумента выглядит как текст, оборванный на полуслове, при
// успешном статусе вызова. Отличить его можно только по виду хвоста.
const tail = body.slice(-1);
if (tail !== '.' && tail !== ')' && tail !== '!' && tail !== ':') {
  throw new Error('комментарий оборван на полуслове, последние символы: ' +
                  JSON.stringify(body.slice(-40)));
}
return [{ json: { action: 'комментарий к существующей задаче',
                  issueNumber: ctx.duplicateNumber, commentUrl: last.html_url,
                  commentChars: body.length, commentsTotal: list.length } }];
